// The avatar validation gauntlet.
//
// These bytes come from an authenticated stranger, which makes this the most
// adversarial input surface in the app. The tests are therefore mostly about
// what is REFUSED, and about the order in which it is refused: every cheap
// check has to reject before sharp is handed anything, because the expensive
// failures happen inside the decoder.
//
// Real image bytes throughout, generated by sharp rather than mocked. A mocked
// decoder would happily agree with whatever the implementation believes.
import { describe, it, expect, beforeAll, afterAll, beforeEach } from "vitest";
import { mkdtemp, rm, stat, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import sharp from "sharp";
import {
  MAX_AVATAR_BYTES,
  ingestAvatar,
  ensureAvatarVariant,
  deleteAvatarFiles,
  __resetAvatarState,
} from "../../src/services/avatarService.js";
import {
  AVATAR_MASTER_SIZE,
  AVATAR_WIDTHS,
  __setAvatarDir,
  avatarUrlFor,
  masterPath,
  variantPath,
} from "../../src/services/avatarStorage.js";

const USER = "clx7k2p9q0000abcd1234efgh";
let dir: string;

/** A real, decodable image of `format` at `w`×`h`. */
async function image(format: "jpeg" | "png" | "webp", w = 600, h = 600): Promise<Buffer> {
  const base = sharp({
    create: { width: w, height: h, channels: 3, background: { r: 200, g: 60, b: 90 } },
  });
  return format === "jpeg" ? base.jpeg().toBuffer() : format === "png" ? base.png().toBuffer() : base.webp().toBuffer();
}

beforeAll(async () => {
  dir = await mkdtemp(path.join(tmpdir(), "soundlog-avatar-"));
  __setAvatarDir(dir);
});

afterAll(async () => {
  await rm(dir, { recursive: true, force: true });
});

beforeEach(() => __resetAvatarState());

describe("ingestAvatar — what it accepts", () => {
  it("accepts JPEG, PNG and WebP and writes a master", async () => {
    for (const format of ["jpeg", "png", "webp"] as const) {
      const { hash, url } = await ingestAvatar(USER, await image(format));
      expect(url).toBe(avatarUrlFor(USER, hash));
      expect((await stat(masterPath(USER, hash))).isFile()).toBe(true);
    }
  });

  it("normalizes the master to a square at AVATAR_MASTER_SIZE", async () => {
    // Deliberately non-square input: the surface paints a circle, so a centre
    // crop is correct here even though it would be wrong for a gatefold scan.
    const { hash } = await ingestAvatar(USER, await image("jpeg", 1200, 400));
    const meta = await sharp(await readFile(masterPath(USER, hash))).metadata();
    expect(meta.width).toBe(AVATAR_MASTER_SIZE);
    expect(meta.height).toBe(AVATAR_MASTER_SIZE);
    expect(meta.format).toBe("webp");
  });

  it("is idempotent — the same bytes give the same hash and URL", async () => {
    const bytes = await image("png");
    const first = await ingestAvatar(USER, bytes);
    const second = await ingestAvatar(USER, bytes);
    expect(second.hash).toBe(first.hash);
    expect(second.url).toBe(first.url);
  });

  it("gives different pictures different URLs, which is what makes immutable honest", async () => {
    const a = await ingestAvatar(USER, await image("png", 600, 600));
    const b = await ingestAvatar(USER, await image("png", 601, 601));
    expect(b.hash).not.toBe(a.hash);
    expect(b.url).not.toBe(a.url);
  });
});

describe("ingestAvatar — the privacy control", () => {
  it("strips EXIF, so a phone photo's GPS is not re-served from our origin", async () => {
    // A JPEG carrying EXIF, including a location. `withMetadata` is what puts
    // it in; the absence of `withMetadata` in the service is what takes it out.
    const withExif = await sharp({
      create: { width: 500, height: 500, channels: 3, background: { r: 10, g: 10, b: 10 } },
    })
      .withMetadata({
        exif: {
          IFD0: { Copyright: "test", Make: "TestPhone" },
          GPS: { GPSLatitudeRef: "N", GPSLongitudeRef: "W" },
        },
      })
      .jpeg()
      .toBuffer();

    // Sanity: the fixture really does carry EXIF, or this test proves nothing.
    expect((await sharp(withExif).metadata()).exif).toBeDefined();

    const { hash } = await ingestAvatar(USER, withExif);
    const out = await sharp(await readFile(masterPath(USER, hash))).metadata();
    expect(out.exif).toBeUndefined();
  });
});

describe("ingestAvatar — what it refuses", () => {
  const reject = async (bytes: Buffer, matching: RegExp) => {
    await expect(ingestAvatar(USER, bytes)).rejects.toThrow(matching);
  };

  it("refuses an empty upload", async () => {
    await reject(Buffer.alloc(0), /empty/i);
  });

  it("refuses anything over the byte cap, before it looks at the format", async () => {
    // Not a valid image either — the size check must fire first, so the error
    // is about size rather than format.
    await reject(Buffer.alloc(MAX_AVATAR_BYTES + 1), /limit is 5 MB/);
  });

  it("refuses SVG — sharp would rasterize it, and it is a script and XXE vector", async () => {
    const svg = Buffer.from(
      '<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><rect width="100" height="100"/></svg>'
    );
    await reject(svg, /not a JPEG, PNG or WebP/);
  });

  it("refuses GIF, deliberately, even though sharp can read it", async () => {
    await reject(Buffer.from("GIF89a\x01\x00\x01\x00\x00\x00\x00;"), /not a JPEG, PNG or WebP/);
  });

  it("refuses a text file wearing an image's name", async () => {
    await reject(Buffer.from("this is definitely a picture, honest"), /not a JPEG, PNG or WebP/);
  });

  it("names HEIC specifically, because it is what a phone will actually send", async () => {
    // An iPhone photo library hands over HEIC unless the file input narrows
    // `accept`, so this is the most likely rejection in practice. A generic
    // "not an image" is useless to someone looking at a photo.
    for (const brand of ["heic", "mif1"]) {
      const heic = Buffer.concat([
        Buffer.from([0, 0, 0, 0x18]),
        Buffer.from("ftyp"),
        Buffer.from(brand),
        Buffer.alloc(16),
      ]);
      await reject(heic, /HEIC/);
    }
  });

  it("does not mistake an unrelated ISO-BMFF file for HEIC", async () => {
    // An MP4 shares the ftyp box; only the brand distinguishes them, and
    // claiming an MP4 is an iPhone photo would send someone down a dead end.
    const mp4 = Buffer.concat([
      Buffer.from([0, 0, 0, 0x18]),
      Buffer.from("ftyp"),
      Buffer.from("isom"),
      Buffer.alloc(16),
    ]);
    await reject(mp4, /not a JPEG, PNG or WebP/);
  });

  it("refuses bytes with a valid signature but a corrupt body", async () => {
    // Passes the magic-byte check, fails in the header parse. The point is that
    // it fails as a 400 about unreadable bytes, not as a crash.
    const fake = Buffer.concat([Buffer.from([0xff, 0xd8, 0xff]), Buffer.alloc(64, 0x41)]);
    await reject(fake, /could not be read/i);
  });

  it("refuses an image that is too large on a side", async () => {
    // 8001×10 is only 80k pixels, so it sails past a megapixel cap — the
    // per-side ceiling is what catches it.
    const wide = await image("png", 8001, 10);
    await reject(wide, /limit is 8000px on a side/);
  });

  it("rejects rather than silently keeping frame one of an animation", async () => {
    // An animated WebP: three frames joined into one multi-page image.
    const frames = await Promise.all(
      [0, 1, 2].map((i) =>
        sharp({
          create: { width: 80, height: 80, channels: 3, background: { r: i * 60, g: 0, b: 0 } },
        })
          .png()
          .toBuffer()
      )
    );
    const animated = await sharp(frames, { join: { animated: true } })
      .webp()
      .toBuffer();

    // Sanity: the fixture really is multi-page.
    expect((await sharp(animated, { animated: true }).metadata()).pages).toBeGreaterThan(1);

    await reject(animated, /Animated images are not supported/);
  });
});

describe("ensureAvatarVariant", () => {
  it("derives every rendition width from the master, at the right size", async () => {
    const { hash } = await ingestAvatar(USER, await image("jpeg"));
    for (const w of AVATAR_WIDTHS) {
      const file = await ensureAvatarVariant(USER, hash, w);
      expect(file).toBe(variantPath(USER, hash, w));
      const meta = await sharp(await readFile(file!)).metadata();
      expect(meta.width).toBe(w);
      expect(meta.height).toBe(w);
    }
  });

  it("serves the second ask from disk", async () => {
    const { hash } = await ingestAvatar(USER, await image("png"));
    const first = await ensureAvatarVariant(USER, hash, 96);
    const mtime = (await stat(first!)).mtimeMs;
    const second = await ensureAvatarVariant(USER, hash, 96);
    expect(second).toBe(first);
    expect((await stat(second!)).mtimeMs).toBe(mtime);
  });

  it("renders once under a concurrent burst", async () => {
    const { hash } = await ingestAvatar(USER, await image("webp"));
    const results = await Promise.all(
      Array.from({ length: 8 }, () => ensureAvatarVariant(USER, hash, 192))
    );
    expect(new Set(results).size).toBe(1);
  });

  it("returns null for a hash we do not hold — a 404, not an error", async () => {
    // Definitive absence. There is no upstream to be uncertain about, so this
    // must never become a 503.
    expect(await ensureAvatarVariant(USER, "0123456789abcdef", 96)).toBeNull();
  });
});

describe("deleteAvatarFiles", () => {
  it("removes the master and every derived rendition", async () => {
    const { hash } = await ingestAvatar(USER, await image("jpeg"));
    for (const w of AVATAR_WIDTHS) await ensureAvatarVariant(USER, hash, w);

    await deleteAvatarFiles(USER, hash);

    // §5's deleteReleaseEverywhere reasoning: a delete that leaves the bytes is
    // not a delete, and for a photograph of a person that is the difference
    // between honouring a deletion request and appearing to.
    await expect(stat(masterPath(USER, hash))).rejects.toThrow();
    for (const w of AVATAR_WIDTHS) {
      await expect(stat(variantPath(USER, hash, w))).rejects.toThrow();
    }
  });

  it("is safe to call for an avatar that is already gone", async () => {
    await expect(deleteAvatarFiles(USER, "0123456789abcdef")).resolves.toBeUndefined();
  });
});
